    ? telefoneLimpo.slice(2)
    : telefoneLimpo;

  ddd = tel.slice(0, 2);
  telefone = tel.slice(2);
}

// 📄 Documento
const cpfCnpjLimpo = onlyNumbers(item.cpfCnpj);

// Tipo de pessoa
const tipoPessoa =
  cpfCnpjLimpo.length === 11 ? "FISICA" :
  cpfCnpjLimpo.length === 14 ? "JURIDICA" :
  null;

// 🧾 Saída normalizada
return [
  {
    json: {
      // Identificador interno
      seu_numero: seuNumero.toString(),

      // Financeiro
      valor: valor,
      data_vencimento: item.dataVencimento || null,
      num_dias_agenda: item.numDiasAgenda || null,

      // Pagador
      pagador: {
        nome: item.nome || null,
        cpf_cnpj: cpfCnpjLimpo || null,
        tipo_pessoa: tipoPessoa,
        ddd: ddd,
        telefone: telefone,
        endereco: item.endereco || null,
        cidade: item.cidade || null,
        uf: item.uf || null,
        cep: onlyNumbers(item.cep) || null
      },

      // Metadados
      origem: "flutterflow",
      recebido_em: new Date().toISOString(),

      // Auditoria
      payload_original: item
    }
  }
];

